import itertools, sys

def is_nae_sat(num_vars, clauses):
    # assignments as bits 0/1 for false/true
    for assign in itertools.product([False, True], repeat=num_vars):
        ok=True
        for clause in clauses:
            vals=[assign[abs(lit)-1] ^ (lit<0) for lit in clause]
            # NAE: not all equal
            if all(vals) or not any(vals):
                ok=False
                break
        if ok:
            return True
    return False

# search for unsat with up to 3 vars, up to 4 clauses
for num_vars in range(1,4):
    lits = []
    for v in range(1,num_vars+1):
        lits.append(v)
        lits.append(-v)
    all_clauses = list(itertools.combinations(lits,3))
    # filter clauses with distinct vars and no var and its neg in same clause
    def valid(cl):
        vars = [abs(l) for l in cl]
        if len(set(vars))<3: return False
        for v in vars:
            if v in [abs(l) for l in cl if l==-v or l==v]:
                pass
        # check not both v and -v present
        for l in cl:
            if -l in cl: return False
        return True
    all_clauses = [c for c in all_clauses if valid(c)]
    # try combos of clauses up to 4
    for r in range(1,5):
        for combo in itertools.combinations(all_clauses, r):
            if not is_nae_sat(num_vars, combo):
                print('found unsat', num_vars, combo)
                sys.exit(0)
print('none found')
