import itertools

def satisfies(clauses, assign):
    # assign dict var->bool
    for clause in clauses:
        vals = []
        for lit in clause:
            v = abs(lit)
            val = assign[v]
            if lit<0:
                val = not val
            vals.append(val)
        # NAE condition: not all equal
        if all(vals) or not any(vals):
            return False
    return True

def find_gadget(vars_needed, target_var):
    # try all combos of clauses up to 3 clauses using given vars
    # vars list includes target_var and other fresh vars
    all_vars = list(range(1, vars_needed+1))
    # generate literals
    lits = []
    for v in all_vars:
        lits.append(v)
        lits.append(-v)
    # generate all possible clauses (distinct vars, no var and its neg)
    def valid(cl):
        vars_ = [abs(l) for l in cl]
        if len(set(vars_))<3: return False
        for l in cl:
            if -l in cl: return False
        return True
    all_clauses = [c for c in itertools.combinations(lits,3) if valid(c)]
    # try combos up to 3 clauses
    for r in range(1,4):
        for combo in itertools.combinations(all_clauses, r):
            # check that in all assignments where target_var is False, clause unsat; and there exists assignment where target_var True and all satisfied.
            ok=True
            # must be satisfiable with target True
            sat_with_true=False
            for assign_vals in itertools.product([False,True], repeat=vars_needed+1):
                assign = {i: assign_vals[i] for i in range(vars_needed+1)}
                if not satisfies(combo, assign):
                    continue
                if assign[target_var]:
                    sat_with_true=True
                else:
                    ok=False
                    break
            if sat_with_true and ok:
                return combo
    return None

# try with target var 1, plus 2 fresh vars (2,3)
combo=find_gadget(3,1)
print(combo)
